public VariantData combine(MaterialData material) {
        UniqueVariantData result = new UniqueVariantData();

        result.key = key + material.key;

        if (material.category != null) {
            result.category = material.category;
        }

        result.attributes = AttributeHelper.collapseRound(AttributeHelper.merge(Arrays.asList(
                attributes,
                material.attributes,
                AttributeHelper.multiplyModifiers(extract.primaryAttributes, material.primary),
                AttributeHelper.multiplyModifiers(extract.secondaryAttributes, material.secondary),
                AttributeHelper.multiplyModifiers(extract.tertiaryAttributes, material.tertiary)
        )));

        result.durability = Math.round(durability + Optional.ofNullable(extract.durability)
                .map(extracted -> extracted * material.durability)
                .orElse(0f));

        result.durabilityMultiplier = durabilityMultiplier + Optional.ofNullable(extract.durabilityMultiplier)
                .map(extracted -> extracted * material.durability)
                .orElse(0f);

        result.integrity = integrity + Optional.ofNullable(extract.integrity)
                .map(extracted -> extracted * (extracted > 0 ? material.integrityGain : material.integrityCost))
                .map(Math::round)
                .orElse(0);

        result.magicCapacity = Math.round(magicCapacity + Optional.ofNullable(extract.magicCapacity)
                .map(extracted -> extracted * material.magicCapacity)
                .orElse(0f));

        result.effects = EffectData.merge(Arrays.asList(
                effects,
                material.effects,
                EffectData.multiply(extract.primaryEffects, material.primary, material.primary),
                EffectData.multiply(extract.secondaryEffects, material.secondary, material.secondary),
                EffectData.multiply(extract.tertiaryEffects, material.tertiary, material.tertiary)
        ));

        result.tools = ToolData.merge(Arrays.asList(
                tools,
                ToolData.multiply(extract.tools, material.toolLevel, material.toolEfficiency)
        ));

        result.aspects = AspectData.merge(aspects, material.aspects);

        if (material.rarity != null && (rarity == null || material.rarity.ordinal() > rarity.ordinal())) {
            result.rarity = material.rarity;
        } else {
            result.rarity = rarity;
        }

        result.glyph = Optional.ofNullable(extract.glyph)
                .map(glyph -> new GlyphData(glyph.textureLocation, glyph.textureX, glyph.textureY, material.tints.glyph))
                .orElse(glyph);

        List<String> availableTextures = Arrays.asList(extract.availableTextures);
        // note that map is run on one of the sub-streams
        result.models = Stream.concat(
                        Arrays.stream(models),
                        Arrays.stream(extract.models).map(model -> MaterialData.kneadModel(model, material, availableTextures)))
                .toArray(IModuleModel[]::new);

        if (tags == null) {
            result.tags = material.tags;
        } else if (material.tags == null) {
            result.tags = tags;
        } else {
            result.tags = Stream.concat(tags.stream(), material.tags.stream()).collect(Collectors.toSet());
        }

        return result;
    }

public static IModuleModel kneadModel(IModuleModel model, MaterialData material, List<String> availableTextures) {
        return model.forMaterial(availableTextures, material);
    }

@Override
        public VariantData deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) throws JsonParseException {
            JsonObject jsonObject = json.getAsJsonObject();

            if (jsonObject.has("materials")) {
                return context.deserialize(json, MaterialVariantData.class);
            } else {
                return context.deserialize(json, UniqueVariantData.class);
            }
        }

public static VariantData merge(VariantData a, VariantData b) {
        if (b.replace) {
            return b;
        }

        VariantData result = new VariantData();


        result.durability = !Objects.equals(b.durability, defaultValues.durability)
                ? b.durability
                : a.durability;
        result.durabilityMultiplier = !Objects.equals(b.durabilityMultiplier, defaultValues.durabilityMultiplier)
                ? b.durabilityMultiplier
                : a.durabilityMultiplier;
        result.integrity = !Objects.equals(b.integrity, defaultValues.integrity)
                ? b.integrity
                : a.integrity;
        result.integrityMultiplier = !Objects.equals(b.integrityMultiplier, defaultValues.integrityMultiplier)
                ? b.integrityMultiplier
                : a.integrityMultiplier;

        result.key = !Objects.equals(b.key, defaultValues.key)
                ? b.key
                : a.key;

        result.category = !Objects.equals(b.category, defaultValues.category)
                ? b.category
                : a.category;

        result.attributes = AttributeHelper.overwrite(a.attributes, b.attributes);
        result.tools = ToolData.overwrite(a.tools, b.tools);
        result.effects = EffectData.overwrite(a.effects, b.effects);
        result.aspects = AspectData.overwrite(a.aspects, b.aspects);

        result.namePriority = b.namePriority != defaultValues.namePriority
                ? b.namePriority
                : a.namePriority;

        result.prefixPriority = b.prefixPriority != defaultValues.prefixPriority
